// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
sampler sampler_pw_noise_lq;
float k1, k2, mask1, mask2, mask3, mask4,
rad1, rad2, rad3, rad4;
vec2 rs, rss, rss0, rs0, uv2, uv3,uv4,
rsk1,rsk2,rsk3,rsk4, uvo, dz1, dz2, dz3, dz4,
Kugel1, Kugel2, Kugel3,Ring, tmp;
vec3 noise, ret1, cathed, sky, fire;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uvo = uv*uAspect.xy;
uv = uv - .1*vec2(q5,q6);
vec2 uv1 = (uv-.5)*uAspect.xy;
//Kugel1
rsk1 = (uv1 + vec2 (q9,q10)) ;
dz1 = normalize(rsk1);
rad1 = q11*length (rsk1) ;
uv4 =  sin(-rad1)*dz1;
mask1 = clamp01(7-10*rad1);
Kugel1 = uv4*mask1;
//Kugel2
rsk2 = (uv1 + vec2 (q13,q14)) ;
dz2 = normalize(rsk2);
rad2 = q15*length (rsk2) ;
uv4 =  sin(-rad2)*dz2;
mask2 = clamp01(7-10*rad2);
Kugel2 = uv4*mask2;
//Kugel3
rsk3 = (uv1 + vec2 (q17,q18)) ;
dz3 = normalize(rsk3);
rad3 = q19*length (rsk3) ;
uv4 =  sin(-rad3)*dz3;
mask3 = clamp01(7-10*rad3);
Kugel3 = uv4*mask3;
//Ring
rsk4 = vec2(length(uv1)-.22, 0.0 ) ;
dz4 = normalize(rsk4);
rad4 = q19*length (rsk4) ;
uv4 =  sin(-rad4)*dz4;
mask4 = clamp01(3-10*rad4);
Ring = uv4*mask4 * 0.0;
vec2 dz = (Kugel2 + Kugel1 + Kugel3 + Ring)*.2;
//******************** STARS
uv1 -= dz;
rss0.x = atan(uv1.x, uv1.y)/3.1416;
rss0.y = .015/(length (uv1));
rss = vec2 (rss0.x,rss0.y+uTime / 4.0);
rss = multiply(rss,mat2(.7,.7,-.7,.7));
float noise = (texture(sampler_pw_noise_lq,rss / 32.0)-.9 >= 0);
tmp = abs(fract(rss * 8.0)-.5);
vec3 dots = clamp01(.04/length(tmp)) *noise;
dots *= clamp01(.2/abs(rss0.y));
dots = clamp01(lum(dots)*lum(dots) * 1.0);
k1 = lum(dots);
dots= k1*vec3( 1.0 ,k1*.8,k1*k1 / 3.0)  ;
//*************************
float z = .2/(length(uv1)+q21);
uv2.y = z + q8;
uv2.x = rss0.x +q7;
uv3 =fract(uv2 * 2.0);
cathed =  texture(sampler_main,uv3)/z;
float cmask = clamp01(1-32*GetBlur1(uv3));
dz1 = normalize(multiply(dz1,mat2(-q9,q10,-q10,-q9)))+.5;
dz2 = normalize(multiply(dz2,mat2(-q13,q14,-q14,-q13)))+.5;
dz3 = normalize(multiply(dz3,mat2(-q17,q18,-q18,-q17)))+.5;
vec3 mod = 1.0 * vec3(.7,.3, 1.0 )* sin(uTime / 7.0);
vec3 blk = (dz1.x/rad1 + dz2.x/rad2 + dz3.x/rad3) *mod;
blk = clamp01(blk);
//Feuer:
float feu = .1+q22;
fire = clamp01(.03*feu/length (uv1)*
(lum(GetBlur2(uv3-vec2( 0.0 , 0.0 )).xy))) ;
//Tasaechl. Feuer; Problem: uv1 passt nicht zu uv3
vec2 uvf = uv1+.0;
fire += clamp01(.001*feu/length (uvf)*
(lum(texture(sampler_main,uvf+.5)))-.01)
* (1.0 / length(uvf));
k1 = lum(fire);
fire = k1*vec3( 1.0 ,k1,k1*k1 / 3.0) ;
vec2 uvs = 32.0 * uvo;
vec3 smask = (texture(sampler_pw_noise_lq,uvs / 256.0)).g-.9;
float stars = clamp01(.3/length(abs(fract(uvs)-.5))*smask);
vec3 moon = clamp01(.02/length(uvo-.2));
sky = stars*stars * clamp01(1-4*moon) + moon ;
ret += sky*(cmask);
ret += fire+dots;
ret += clamp01(.0+moon+blk)*cathed + blk;
  fragColor = vec4(ret, 1.0);
}

